assert not (HERE / 'PREREG.json').exists()
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
s0 = json.loads((HERE / 'step0.json').read_text()); dc = json.loads((HERE / 'data_check.json').read_text())
td = s0['train_desc']
